extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var audio = await instantiate_script("res://assets/audio/audio.gd")
	if not check("instantiate", audio != null, "Lo script res://assets/audio/audio.gd deve potersi istanziare"):
		return

	if not check("play_music_func", has_function(audio, "play_music"), "AudioManager deve contenere la funzione play_music"):
		return
	if not check("stop_music_func", has_function(audio, "stop_music"), "AudioManager deve contenere la funzione stop_music"):
		return
	if not check("play_sfx_func", has_function(audio, "play_sfx"), "AudioManager deve contenere la funzione play_sfx"):
		return
	if not check("get_active_func", has_function(audio, "get_active_music_player"), "AudioManager deve contenere la funzione get_active_music_player"):
		return

	var test_stream := AudioStreamWAV.new()
	var bytes := PackedByteArray()
	bytes.resize(44100)
	test_stream.data = bytes

	call_if_exists(audio, "play_music", [test_stream, 0.1])
	var active = call_if_exists(audio, "get_active_music_player")
	if not check("active_player", active != null, "Dopo play_music() deve esserci un riproduttore attivo"):
		return

	var is_playing: bool = bool(get_prop(active, "playing", false))
	check("music_playing", is_playing, "Il riproduttore musicale attivo deve aver avviato la riproduzione")

	var node_audio := audio as Node
	var child_count_before: int = node_audio.get_child_count()
	call_if_exists(audio, "play_sfx", [test_stream])
	var child_count_after: int = node_audio.get_child_count()
	check("sfx_spawned", child_count_after > child_count_before, "La funzione play_sfx() deve creare un nuovo nodo AudioStreamPlayer per l'effetto")

	call_if_exists(audio, "stop_music", [0.1])
	await wait_seconds(0.15)
	var active_after = call_if_exists(audio, "get_active_music_player")
	var is_still_playing: bool = bool(get_prop(active_after, "playing", false)) if active_after != null else false
	check("music_stopped", active_after == null or not is_still_playing, "Dopo stop_music() la musica deve essersi fermata")

