extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var screen = await instantiate_scene("res://story/story_screen.tscn")
	if not check("scene_loaded", screen != null, "La scena res://story/story_screen.tscn deve istanziarsi correttamente"):
		return

	var audio_mgr = find_by_name(screen, "AudioManager") as AudioManager
	if not check("audio_mgr_found", audio_mgr != null, "Nella scena story_screen.tscn deve essere presente un nodo AudioManager"):
		return

	var interpreter = find_by_name(screen, "StoryInterpreter") as StoryInterpreter
	if not check("interpreter_found", interpreter != null, "Nella scena story_screen.tscn deve essere presente il nodo StoryInterpreter"):
		return

	check("audio_mgr_assigned", interpreter.audio_manager == audio_mgr, "La proprietà esportata audio_manager di StoryInterpreter deve puntare al nodo AudioManager")

	if not check("has_execute_cmd", has_function(interpreter, "execute_command"), "StoryInterpreter deve definire la funzione execute_command(command: Dictionary)"):
		return

	await interpreter.execute_command({
		"type": "music",
		"path": "res://assets/audio/music_loop.wav",
		"fade": 0.4
	})
	await wait_frames(2)

	var active_player = audio_mgr.get_active_music_player()
	check("music_playing", active_player != null and active_player.playing, "Il comando 'music' deve avviare la riproduzione della traccia specificata")

	if active_player:
		check("music_fading_in", active_player.volume_db < -5.0, "Durante la dissolvenza il volume deve partire basso (volume rilevato: %.1f dB)" % active_player.volume_db)

	await wait_seconds(0.5)
	if active_player:
		check("music_fade_ended", active_player.volume_db > -1.0, "Al termine della dissolvenza il volume deve raggiungere circa 0 dB (volume rilevato: %.1f dB)" % active_player.volume_db)

	await interpreter.execute_command({
		"type": "sfx",
		"path": "res://assets/audio/jump.wav"
	})
	await wait_frames(2)

	var sfx_found := false
	for child in audio_mgr.get_children():
		if child is AudioStreamPlayer and child != active_player:
			if child.playing:
				sfx_found = true
				break
	check("sfx_playing", sfx_found, "Il comando 'sfx' deve creare un riproduttore dedicato e avviare il suono senza fermare la musica")

	await interpreter.execute_command({
		"type": "stop_music",
		"fade": 0.3
	})
	await wait_seconds(0.4)
	var stopped_player = audio_mgr.get_active_music_player()
	check("music_stopped", stopped_player == null or not stopped_player.playing, "Il comando 'stop_music' deve arrestare la musica al termine della dissolvenza in uscita")

